--
-- Name: ai_agent_actions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_agent_actions (
    id text NOT NULL,
    actor text DEFAULT ''::text NOT NULL,
    prompt text DEFAULT ''::text NOT NULL,
    tool_name text DEFAULT ''::text NOT NULL,
    args_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    preview_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    requires_confirmation boolean DEFAULT true NOT NULL,
    result_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_message text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    executed_at timestamp with time zone,
    CONSTRAINT ai_agent_actions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'executed'::text, 'cancelled'::text, 'failed'::text])))
);


